tool.command:
@SHELL_OPTIONS@
## create symlinks to input datasets #if $otu.is_of_type("mothur.list"): ln -s '$otu' input.list && #elif $otu.is_of_type("mothur.rabund"): ln -s '$otu' input.rabund && #elif $otu.is_of_type("mothur.sabund"): ln -s '$otu' input.sabund && #else: ln -s '$otu' input.shared && #end if
echo 'estimator.single( #if $calc: calc=$calc, #end if #if $label: label=${ str($label).replace(",","-") }, #end if freq=$freq, #if $coverage: coverage=$coverage, #end if #if $otu.is_of_type("mothur.list"): list=input.list #elif $otu.is_of_type("mothur.rabund"): rabund=input.rabund #elif $otu.is_of_type("mothur.sabund"): sabund=input.sabund #else: shared=input.shared #end if )' | sed 's/ //g; s/,)$/)/' ## mothur trips over whitespace; a trailing comma segfaults mothur >1.42 | mothur | tee mothur.out.log
